"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":8000}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false,\"credit_cents\":1000},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":100,\"quantity\":2}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[],\"member\":false},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":99,\"quantity\":3}],\"member\":true,\"credit_cents\":5},\"expected\":{\"total_cents\":262}}]},{\"candidate\":\"maple\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":8000}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false,\"credit_cents\":1000},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":100,\"quantity\":2}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[],\"member\":false},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":99,\"quantity\":3}],\"member\":true,\"credit_cents\":5},\"expected\":{\"total_cents\":262}}]},{\"candidate\":\"birch\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/birch/checkout.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":8000}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false,\"credit_cents\":1000},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":100,\"quantity\":2}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[],\"member\":false},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":99,\"quantity\":3}],\"member\":true,\"credit_cents\":5},\"expected\":{\"total_cents\":262}}]},{\"candidate\":\"willow\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/willow/checkout.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":8000}},{\"input\":{\"lines\":[{\"unit_cents\":10000,\"quantity\":1}],\"member\":false,\"credit_cents\":1000},\"expected\":{\"total_cents\":9000}},{\"input\":{\"lines\":[{\"unit_cents\":105,\"quantity\":1}],\"member\":true},\"expected\":{\"total_cents\":95}},{\"input\":{\"lines\":[{\"unit_cents\":100,\"quantity\":2}],\"member\":true,\"credit_cents\":1000},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[],\"member\":false},\"expected\":{\"total_cents\":0}},{\"input\":{\"lines\":[{\"unit_cents\":99,\"quantity\":3}],\"member\":true,\"credit_cents\":5},\"expected\":{\"total_cents\":262}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

